#include <bits/stdc++.h>
using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int L, C;
    cin >> L >> C;
    int P;
    cin >> P;
    vector<string> grid(L, string(C, '.'));
    for (int i = 0; i < P; i++){
        int x, y;
        cin >> x >> y;
        --x; --y;
        grid[x][y] = '#'; // peça preta
    }

    // Uma peça branca só pode ocupar casas não-pretas vizinhas (ortogonalmente)
    // de alguma peça preta. Constrói máscara de candidatos por linha.
    vector<int> cand(L, 0);
    for (int r = 0; r < L; r++){
        for (int c = 0; c < C; c++){
            if (grid[r][c] == '#') continue;
            bool ok = false;
            if (r > 0 && grid[r-1][c] == '#') ok = true;
            if (r + 1 < L && grid[r+1][c] == '#') ok = true;
            if (c > 0 && grid[r][c-1] == '#') ok = true;
            if (c + 1 < C && grid[r][c+1] == '#') ok = true;
            if (ok) cand[r] |= (1 << c);
        }
    }

    // Máscaras válidas por linha: sem duas peças brancas lado a lado
    vector<int> valid;
    for (int m = 0; m < (1 << C); m++){
        if ((m & (m << 1)) == 0) valid.push_back(m);
    }

    const long long NEG = LLONG_MIN / 4;
    vector<long long> dp(1 << C, NEG), ndp(1 << C, NEG);

    // Primeira linha
    for (int m : valid){
        if ((m & ~cand[0]) == 0) dp[m] = __builtin_popcount(m);
    }

    // Demais linhas: proibido peças brancas verticalmente adjacentes
    for (int r = 1; r < L; r++){
        fill(ndp.begin(), ndp.end(), NEG);
        for (int m : valid){
            if (m & ~cand[r]) continue;      // só células candidatas
            int cost = __builtin_popcount(m);
            for (int pm : valid){
                if (dp[pm] == NEG) continue;
                if (pm & m) continue;        // conflito vertical
                long long val = dp[pm] + cost;
                if (val > ndp[m]) ndp[m] = val;
            }
        }
        swap(dp, ndp);
    }

    long long ans = 0;
    for (int m = 0; m < (1 << C); m++){
        ans = max(ans, dp[m]);
    }

    cout << ans << "\n";
    return 0;
}
